var e={UNDERWEIGHT:`Underweight`,HEALTHY:`Healthy Weight`,OVERWEIGHT:`Overweight`,OBESE:`Obese`};e.UNDERWEIGHT,e.HEALTHY,e.OVERWEIGHT,e.OBESE;var t=[{id:`sedentary`,label:`Sedentary`,desc:`Little or no exercise`},{id:`light`,label:`Light Exercise`,desc:`1-3 days/week`},{id:`moderate`,label:`Moderate Exercise`,desc:`3-5 days/week`},{id:`heavy`,label:`Heavy Exercise`,desc:`6-7 days/week`},{id:`athlete`,label:`Athlete`,desc:`Hard daily training`}],n=[{id:`moderate`,label:`Moderate Carb`,ratio:`30/35/35`,protein:.3,fat:.35,carb:.35},{id:`lower`,label:`Lower Carb`,ratio:`40/40/20`,protein:.4,fat:.4,carb:.2},{id:`higher`,label:`Higher Carb`,ratio:`30/20/50`,protein:.3,fat:.2,carb:.5}];function r(e,t){let n=e*t.protein,r=e*t.fat,i=e*t.carb;return{protein:{grams:Math.round(n/4),calories:Math.round(n)},fat:{grams:Math.round(r/9),calories:Math.round(r)},carb:{grams:Math.round(i/4),calories:Math.round(i)}}}export{n,r,t};